import {waterOpsShowcase} from './waterops-keynote.js?v=waterops-partnership-1';
import {numOpsScript,numOpsBeat} from './numops-script.js?v=waterops-partnership-1';
const icon=(type)=>`<svg class="no-icon" viewBox="0 0 48 48" aria-hidden="true">${({sensor:'<circle cx="24" cy="24" r="5"/><path d="M16 16a11 11 0 0 0 0 16M32 16a11 11 0 0 1 0 16M10 10a20 20 0 0 0 0 28M38 10a20 20 0 0 1 0 28"/>',database:'<ellipse cx="24" cy="10" rx="15" ry="6"/><path d="M9 10v27c0 8 30 8 30 0V10M9 23c0 8 30 8 30 0"/>',file:'<path d="M13 5h17l9 9v29H13zM30 5v10h9M19 23h14M19 30h14M19 37h9"/>',model:'<path d="M8 12l16-8 16 8v24l-16 8-16-8zM8 12l16 9 16-9M24 21v23"/>',water:'<path d="M24 3C20 12 8 22 8 30a16 16 0 0 0 32 0C40 22 28 12 24 3Z"/><path d="M15 31c0 6 4 9 9 9"/>',check:'<path d="M9 24l10 10L39 12"/>',chip:'<rect x="11" y="11" width="26" height="26" rx="4"/><path d="M18 1v10M30 1v10M18 37v10M30 37v10M1 18h10M1 30h10M37 18h10M37 30h10"/><path d="M19 19h10v10H19z"/>'})[type]||''}</svg>`;
const wire=(d,i=0)=>`<path class="no-wire" d="${d}"/><path class="no-current" d="${d}" style="--delay:${i*.55}s"/>`;
const routes=(paths)=>`<svg class="no-routes" viewBox="0 0 1000 500" preserveAspectRatio="none" aria-hidden="true">${paths.map((d,i)=>wire(d,i)).join('')}</svg>`;
const graph=(variant='forecast')=>`<svg class="no-chart" viewBox="0 0 660 310" aria-label="${variant==='forecast'?'歷史數據與預測趨勢示意':'訊號曲線示意'}"><defs><linearGradient id="no-area-${variant}" x2="0" y2="1"><stop stop-color="#739aff" stop-opacity=".35"/><stop offset="1" stop-color="#739aff" stop-opacity="0"/></linearGradient></defs>${[70,130,190,250].map(y=>`<path class="no-grid" d="M15 ${y}H645"/>`).join('')}<path class="no-area" fill="url(#no-area-${variant})" d="M15 236L55 218 95 226 135 180 175 202 215 161 255 179 295 137 335 149 375 112 415 124 455 91 495 108 535 70 575 88 615 58 645 68V290H15Z"/><path class="no-line" d="M15 236L55 218 95 226 135 180 175 202 215 161 255 179 295 137 335 149 375 112 415 124"/><path class="no-line no-predict" d="M415 124L455 91 495 108 535 70 575 88 615 58 645 68"/><path class="no-chart-divider" d="M415 30V290"/><circle class="no-beacon" cx="415" cy="124" r="6"/><text x="20" y="305">歷史資料</text><text x="475" y="305">預測示意</text></svg>`;
function overview(){return `<section class="no-overview"><div class="no-opening-copy"><p class="no-kicker">NUMOPS / LEARNING FROM EXPERIENCE</p><h1>從看懂現場，<br>到<span>預見下一步。</span></h1><p>每一次量測，都是經驗。<br>讓經驗，成為可以使用的規律。</p><div class="no-three-words"><span>數據</span><i></i><span>學習</span><i></i><span>決策</span></div></div><div class="no-signal-sculpture"><div class="no-sculpture-orbit"></div><div class="no-sculpture-orbit second"></div><div class="no-wave-stack">${Array.from({length:12},(_,i)=>`<svg viewBox="0 0 700 240" style="--i:${i}" aria-hidden="true"><path d="M0 160C60 160 70 40 140 70S220 220 290 130 340 15 410 85 500 185 550 100 630 35 700 50"/></svg>`).join('')}</div><div class="no-signal-caption"><b>DATA BECOMES INTELLIGENCE</b><span>AutoML <i>＋</i> 專家系統</span></div><span class="no-orbit-dot one"></span><span class="no-orbit-dot two"></span></div></section>`;}
function signals(){return `<div class="no-flow no-signal-flow">${routes(['M230 88C340 88 300 250 420 250','M230 250H420','M230 412C340 412 300 250 420 250','M625 250H730'])}<div class="no-sources">${[['sensor','設備訊號','溫度 · 振動 · 流量'],['database','營運紀錄','SCADA · MES · ERP'],['file','歷史資料','CSV · XLS']].map(([i,h,p])=>`<article>${icon(i)}<div><h2>${h}</h2><p>${p}</p></div></article>`).join('')}</div><div class="no-center-node">${icon('chip')}<small>DATA CONTEXT</small><h2>對齊情境</h2><p>設備 · 時間 · 目標</p></div><div class="no-dataset"><div><span>DATASET</span><b>可用於學習的資料</b></div><table><thead><tr><th>時間</th><th>設備</th><th>特徵</th></tr></thead><tbody>${Array.from({length:6},(_,i)=>`<tr style="--i:${i}"><td>t + ${i}</td><td>LINE A</td><td><i style="width:${35+i*7}%"></i></td></tr>`).join('')}</tbody></table><p>將數字，放回要解決的問題。</p></div></div>`;}
function tasks(){return `<div class="no-task-panels"><article class="no-task"><p>01 / UNDERSTAND</p><h2>現在，發生什麼？</h2><div class="no-status-field">${Array.from({length:35},(_,i)=>`<i class="${[9,17,24].includes(i)?'anomaly':''}" style="--i:${i}"></i>`).join('')}</div><footer><b>分類 · 異常偵測</b><span>辨識狀態與不尋常變化</span></footer></article><article class="no-task"><p>02 / PREDICT</p><h2>接著，會如何變化？</h2>${graph()}<footer><b>回歸 · 時間序列</b><span>預測數值與未來走勢</span></footer></article><article class="no-task"><p>03 / DISCOVER</p><h2>哪些，有共同特徵？</h2><div class="no-clusters">${Array.from({length:42},(_,i)=>`<i style="--x:${20+(i%3)*30+Math.sin(i*2.7)*12}%;--y:${48+Math.cos(i*1.9)*29}%;--c:${['#82a7ff','#86d5d5','#d8b88a'][i%3]};--i:${i}"></i>`).join('')}</div><footer><b>分群分析</b><span>發現資料中的相似性</span></footer></article></div>`;}
function automl(){return `<div class="no-flow no-automl">${routes(['M230 250H325V75H410','M325 250V192H410','M325 250V308H410','M325 250V425H410','M650 75H700V250H780','M650 192H700V250','M650 308H700V250','M650 425H700V250'])}<div class="no-ml-input">${icon('database')}<small>INPUT</small><h2>資料 × 目標</h2><p>選擇要預測的結果</p><div class="no-data-bars">${Array.from({length:12},(_,i)=>`<i style="--i:${i};height:${25+(i*17)%65}%"></i>`).join('')}</div></div><div class="no-candidates">${['A','B','C','D'].map((n,i)=>`<article style="--i:${i}"><span>MODEL ${n}</span><div><i></i></div><b>訓練與評估</b></article>`).join('')}</div><div class="no-ml-output"><div class="no-model-cube">${icon('model')}</div><small>AUTOML</small><h2>讓模型競爭</h2><p>比較表現<br>選出適合的模型</p></div></div>`;}
function expert(){return `<div class="no-dual"><article><span class="no-kicker">LEARN FROM DATA</span><h2>從資料學習</h2>${graph('dual')}<div class="no-dual-method"><strong>AutoML</strong><span>找出資料中的模式</span></div></article><div class="no-dual-plus">＋</div><article class="no-expert"><span class="no-kicker">LEARN FROM PEOPLE</span><h2>把專家經驗留下</h2><div class="no-rule"><span>WHEN</span><b>狀態符合條件</b><i></i><span>THEN</span><b>採用對應策略</b></div><div class="no-dual-method"><strong>專家系統</strong><span>將知識整理成規則庫</span></div></article><p class="no-dual-result">讓數據與經驗，成為同一份決策能力。</p></div>`;}
const screenInfo={prepare:['資料預處理','資料來源 → 處理方式 → 資料集'],training:['建立模型','選擇任務 → 設定目標 → AutoML'],analysis:['模型分析','模型排行 · 測試集分析 · 特徵重要性']};
function screen(asset){const [name,caption]=screenInfo[asset];return `<figure class="no-screen" data-no-asset="${asset}"><div class="no-window-bar"><b>NumOps <span>/ ${name}</span></b><span>OFFICIAL PRODUCT VIEW</span></div><div class="no-screen-image"><img src="./assets/numops/${asset}.webp" alt="NumOps 官方${name}介面"/></div><figcaption>${caption}</figcaption></figure>`;}
function oven(){return `<div class="no-oven"><figure><img src="./assets/pitch-oven-temperature.png" alt="智慧烤箱溫控實際案例，多點溫度曲線"/><figcaption>AIWin Pitch v5 · 智慧烤箱溫控</figcaption></figure><div class="no-oven-system"><div class="no-oven-metrics"><p><b>27</b><span>風門</span></p><p><b>15</b><span>溫度點</span></p></div><div class="no-oven-chamber">${Array.from({length:15},(_,i)=>`<i style="--i:${i}"><b></b></i>`).join('')}<span>多點量測</span></div><div class="no-oven-loop"><span>NumOps<br><small>模型與規則</small></span><i>⇄</i><span>WinEdge-N<br><small>現場推論</small></span></div><p>量測、判斷、調整。<br>讓經驗進入每一次運轉。</p></div></div>`;}
function edgeHost(){return `<svg class="no-edge-host" viewBox="0 0 500 280" aria-label="現場 Edge 工業主機示意"><defs><linearGradient id="no-metal" x2="0" y2="1"><stop stop-color="#8897b0"/><stop offset="1" stop-color="#263348"/></linearGradient></defs><path fill="#26384a" d="M40 90L110 35H450L405 90Z"/><path fill="url(#no-metal)" d="M40 90H405V225H40Z"/><path fill="#172637" d="M405 90L450 35V175L405 225Z"/>${Array.from({length:15},(_,i)=>`<path fill="#718399" d="M${58+i*23} 84L${117+i*21} 38v14l-${59-i*2} 46Z"/>`).join('')}<rect x="57" y="112" width="330" height="93" rx="5" fill="#09131e"/><rect x="77" y="143" width="48" height="35" fill="#617786"/><rect x="82" y="149" width="38" height="23" fill="#0b1824"/><rect x="141" y="143" width="48" height="35" fill="#617786"/><rect x="146" y="149" width="38" height="23" fill="#0b1824"/><path stroke="#8c9bab" stroke-width="5" d="M215 151h28v18h-28zM259 151h28v18h-28z" fill="#060e18"/><circle class="no-host-led" cx="350" cy="147" r="4"/><circle class="no-host-led" cx="350" cy="166" r="4"/><text x="225" y="136">EDGE COMPUTING</text></svg>`;}
function deploy(){return `<div class="no-deploy"><div class="no-deploy-model"><div class="no-model-cube">${icon('model')}</div><span>TRAINED & VALIDATED</span><h2>模型與規則</h2><p>把學到的能力，帶回現場。</p></div><div class="no-deploy-stream"><i></i><i></i><i></i></div><div class="no-deploy-edge">${edgeHost()}<h2>WinEdge-N</h2><p>現場數據推論</p></div><div class="no-deploy-outputs"><article>${icon('sensor')}<div><h3>設備與儀表板</h3><p>即時判斷 · 現場回饋</p></div></article><article>${icon('database')}<div><h3>API 串接</h3><p>連進既有工作系統</p></div></article><article>${icon('file')}<div><h3>批次預測</h3><p>大量資料 · 結果輸出</p></div></article></div><div class="no-deploy-feedback"><span>新的現場經驗，回到下一次學習。</span><i></i></div></div>`;}
const scenes={signals,tasks,automl,expert,oven,waterops:waterOpsShowcase,deploy};
const miniBrick=(label,i)=>`<div class="no-fusion-brick" style="--i:${i}"><i></i><i></i><i></i><span>${label}</span></div>`;
export function numOpsUI(state){
 if(state.phase==='overview')return {key:'overview',layout:'full',action:'讀懂數據',note:'承接前一段模型學習，從感知現場走到理解數據。三段依序是讀懂數據、學會預測、回到現場；全程由講者推進。',html:overview()};
 if(state.phase==='fusing')return {key:'fusing',layout:'fusion',note:'三段經驗匯聚為 NumOps。',html:`<section class="no-fusion"><p class="no-kicker">EXPERIENCE BECOMES INTELLIGENCE</p><h1>讓規律，成為能力。</h1><div class="no-fusion-vortex">${['DATA','AutoML','EXPERT','VALIDATE','WaterOps','EDGE'].map(miniBrick).join('')}</div><div class="no-fusion-flash"></div></section>`};
 if(state.phase==='born')return {key:'born',layout:'hero',action:'前往 WinChat 知識與行動',note:'NumOps 結合資料處理、AutoML 與專家系統，將能力帶回現場。接著進入 WinChat，從理解數據走向企業知識與行動。',html:`<section class="no-product-reveal"><p class="no-kicker">INTELLIGENT DATA AI PLATFORM</p><h1>NumOps<span>讓數據，<br>成為決策能力。</span></h1><p>AutoML ＋ 專家系統</p><div><span>資料準備</span><i>→</i><span>模型學習</span><i>→</i><span>現場應用</span></div></section><div class="no-product-halo"></div>`};
 const b=numOpsBeat(state),section=['讀懂數據','學會預測','回到現場'][state.selected];
 return {key:`${state.selected}:${state.beat}`,layout:'full',action:state.selected===2&&state.beat===numOpsScript[2].length-1?'揭曉 NumOps':`NumOps 下一段`,note:b.note,html:`<section class="no-keynote" data-no-scene="${b.scene}" data-no-beat="${state.selected}:${state.beat}"><header><div><p class="no-kicker">NUMOPS / ${section}</p><h1>${b.title}</h1></div><p>${b.subtitle}</p></header><div class="no-stage">${b.scene==='screen'?screen(b.asset):scenes[b.scene]()}</div><footer><span>${b.scene.startsWith('water')?'GSD × AIWIN / WATEROPS':'NUMOPS'}</span><small>${b.scene==='screen'?'官方產品介面':b.scene==='oven'?'專案素材 · 流程示意':b.scene.startsWith('water')?'矽品中科廠公開案例 · 來源：WaterOps 2026.06.05 · 資料流為示意':'功能概念動畫'}</small></footer></section>`};
}
// Move between full-size visual scenes; leave every beat on screen until the speaker advances.
export function createNumOpsStage({root,story,detail}){
 let key=null,animations=[],oldLayer=null;
 const cancel=()=>{animations.forEach(a=>a.cancel());animations=[];oldLayer?.remove();oldLayer=null;};
 function reset(){cancel();key=null;delete root.dataset.numopsLayout;}
 function render(state,ui){
  story.hidden=true;root.dataset.numopsLayout=ui.layout;
  if(key===ui.key)return;
  const backward=key&&ui.key.includes(':')&&key.includes(':')&&ui.key<key;
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  cancel();
  if(key===null||reduced)detail.replaceChildren();
  if(detail.firstElementChild&&key&&!reduced){oldLayer=document.createElement('div');oldLayer.className='no-outgoing';oldLayer.setAttribute('aria-hidden','true');oldLayer.inert=true;oldLayer.append(...detail.childNodes);detail.append(oldLayer);}
  const frame=document.createElement('div');frame.className='no-frame';frame.innerHTML=ui.html;detail.append(frame);
  if(!reduced){
   const duration=state.phase==='selecting'?1650:state.phase==='born'?1100:850;
   const direction=backward?-1:1;
   if(oldLayer)animations.push(oldLayer.animate([{opacity:1,transform:'none'},{opacity:0,transform:`translateX(${-direction*60}px) scale(.96)`}],{duration:300,easing:'ease-in-out',fill:'both'}));
   animations.push(frame.animate([{opacity:0,transform:`translateX(${direction*90}px) scale(${state.phase==='selecting'?1.10:1.025})`},{opacity:1,transform:'none'}],{duration:duration-250,delay:oldLayer?250:0,easing:'cubic-bezier(.16,1,.3,1)',fill:'both'}));
   const outgoing=oldLayer;animations.at(-1).finished.then(()=>{outgoing?.remove();if(oldLayer===outgoing)oldLayer=null;}).catch(()=>{});
  }else{oldLayer?.remove();oldLayer=null;}
  key=ui.key;
 }
 return {reset,render};
}
